"use client"

import { usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import {
  Tree,
  TreeItem,
  TreeItemIndicator,
  TreeItemLabel,
  treeFromPaths,
  visibleTreeRows,
  type TreeItemData,
} from "@ui-sdk/react/tree"
import {
  ChevronRightIcon,
  FileCodeIcon,
  FileIcon,
  FileImageIcon,
  FileJsonIcon,
  FileTextIcon,
  FolderIcon,
  FolderOpenIcon,
} from "lucide-react"
import { memo, useCallback, useMemo, type CSSProperties, type FocusEvent } from "react"

import { gitTree, type GitTreeOptions } from "@/components/ui/git-tree-primitive"
import { useInstanceState } from "@/components/ui/use-instance-state"
import { useTrailRows } from "@/components/ui/use-trail-rows"
import { gitStatusTones, indexGitFiles, type GitFileStatus, type GitTreeFile } from "@/lib/git-status"
import type { Tone } from "@/lib/tone"
import { cn } from "@/lib/utils"

type GitTreeLabels = {
  /** Read after a changed file's name: "Modified". */
  status: Record<GitFileStatus, string>
  /** The one-letter mark shown beside a changed file. */
  mark: Record<GitFileStatus, string>
  /** Read after a folder that holds changes. */
  changedFolder: string
  /** Read after a renamed file: "from src/old.ts". */
  renamedFrom: (path: string) => string
}

const gitTreeLabels: GitTreeLabels = {
  status: { added: "Added", modified: "Modified", deleted: "Deleted", renamed: "Renamed" },
  mark: { added: "A", modified: "M", deleted: "D", renamed: "R" },
  changedFolder: "Has changes",
  renamedFrom: (path) => `from ${path}`,
}

type GitTreeProps = Omit<PartProps<"div">, "children" | "onSelect" | "defaultValue"> & {
  /** Names the tree, for screen readers and agents. */
  "aria-label": string
  /** Every path at the commit, as strings or with a status; a path ending in `/` is an empty folder. */
  files: readonly (string | GitTreeFile)[]
  /** Open folders. By default the folders that hold a change start open. */
  expanded?: readonly string[]
  defaultExpanded?: readonly string[]
  onExpandedChange?: GitTreeOptions["onExpandedChange"]
  /** The file shown elsewhere, like the one a diff is open on. */
  current?: string | null
  /** Click or Enter on a file. */
  onOpenFile?: GitTreeOptions["onOpenFile"]
  labels?: Partial<GitTreeLabels>
  /** A row's estimated height in px before it is measured. Default 32. */
  estimateSize?: number
  /**
   * Find in page reaches files and folders scrolled out of view, by name, through UI SDK's virtualizer and its
   * findable layers, built once the page is idle after its first paint. Off by default: on 100,000 files it costs
   * up to a frame on some held-arrow presses (p95 about 16 ms against 12 ms).
   */
  findable?: boolean
}

const markClassNames: Record<Tone, string> = {
  neutral: "text-muted-foreground",
  info: "text-info",
  success: "text-success",
  warning: "text-warning",
  destructive: "text-destructive",
  violet: "text-violet",
}

type FileKind = "code" | "data" | "image" | "text" | "other"

const fileKinds: [RegExp, FileKind][] = [
  [/\.(?:[cm]?[jt]sx?|css|html|vue|svelte|py|rb|go|rs|java|kt|swift|c|h|cpp|sh)$/i, "code"],
  [/\.(?:json|ya?ml|toml|lock)$/i, "data"],
  [/\.(?:png|jpe?g|gif|svg|webp|avif|ico)$/i, "image"],
  [/\.(?:md|mdx|txt|rst)$|(?:^|\/)(?:README|LICENSE|CHANGELOG)[^/]*$/i, "text"],
]

function NodeIcon({ folder, expanded, path }: { folder: boolean; expanded: boolean; path: string }) {
  if (folder) return expanded ? <FolderOpenIcon /> : <FolderIcon />
  switch (fileKinds.find(([pattern]) => pattern.test(path))?.[1]) {
    case "code":
      return <FileCodeIcon />
    case "data":
      return <FileJsonIcon />
    case "image":
      return <FileImageIcon />
    case "text":
      return <FileTextIcon />
    default:
      return <FileIcon />
  }
}

const rowClassName =
  "relative flex h-control-sm min-w-0 items-center gap-inline rounded-control pe-(--item-padding-x) text-body-sm transition-colors duration-micro ease-standard group-focus-visible/git-row:bg-accent group-focus-visible/git-row:ring-2 group-focus-visible/git-row:ring-ring hover:bg-accent data-current:bg-accent data-current:font-medium data-current:text-accent-foreground [&>svg]:size-4 [&>svg]:shrink-0"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- each level indents by a chevron plus the inline gap, from the item inset
const levelIndent = "ps-[calc((var(--tree-level)-1)*var(--git-tree-indent)+var(--item-padding-x))]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- one level of nesting (a chevron plus the inline gap), and the scroller's cap with `findable` (UI SDK's virtualizer needs it bounded)
const indentSize = "[--git-tree-indent:calc(0.875rem+var(--gap-inline))] [--git-tree-height:40rem]"

type RowContext = {
  status: ReadonlyMap<string, GitTreeFile>
  changedFolders: ReadonlySet<string>
  labels: GitTreeLabels
}

type GitTreeRowProps = {
  item: TreeItemData
  level: number
  index: number
  expanded: boolean
  context: RowContext
  /** Where the row sits in the tree's box while it's virtualized, in px. */
  top?: number
  measure?: (index: number, el: HTMLElement | null) => () => void
  /** Fills the name, so find in page finds the row while it isn't rendered (`findableText`). */
  textSlot?: (index: number, el: HTMLElement | null) => () => void
}

const GitTreeRow = memo(function GitTreeRow({
  item,
  level,
  index,
  expanded,
  context,
  top,
  measure,
  textSlot,
}: GitTreeRowProps) {
  const folder = item.children !== undefined
  const file = context.status.get(item.value)
  const changedFolder = folder && context.changedFolders.has(item.value)
  const { labels } = context
  return (
    <TreeItem
      value={item.value}
      ref={measure ? (el: HTMLElement | null) => measure(index, el) : undefined}
      data-index={index}
      data-status={file?.status}
      style={{ "--tree-level": level, top } as CSSProperties}
      className={cn("group/git-row outline-none", top !== undefined && "absolute inset-x-0")}
    >
      <TreeItemLabel className={cn(rowClassName, levelIndent)}>
        {folder ? (
          <TreeItemIndicator className="inline-flex shrink-0 text-muted-foreground transition-transform duration-micro ease-standard data-expanded:rotate-90 rtl:-scale-x-100 [&_svg]:size-3.5">
            <ChevronRightIcon />
          </TreeItemIndicator>
        ) : (
          <span aria-hidden="true" className="size-3.5 shrink-0" />
        )}
        <span
          className={cn(
            "inline-flex shrink-0 text-muted-foreground [&_svg]:size-4",
            file?.status && markClassNames[gitStatusTones[file.status]],
          )}
        >
          <NodeIcon folder={folder} expanded={expanded} path={item.value} />
        </span>
        <span
          className={cn("min-w-0 truncate", file?.status === "deleted" && "line-through decoration-destructive")}
          title={file?.from ? `${file.from} → ${item.value}` : undefined}
          ref={textSlot ? (el: HTMLElement | null) => textSlot(index, el) : undefined}
        >
          {textSlot ? null : item.label}
        </span>
        {file?.status && (
          <span className="sr-only">
            , {labels.status[file.status]}
            {file.from ? `, ${labels.renamedFrom(file.from)}` : ""}
          </span>
        )}
        {changedFolder && <span className="sr-only">, {labels.changedFolder}</span>}
        <span aria-hidden="true" className="ms-auto flex shrink-0 items-center">
          {file?.status ? (
            <span
              data-slot="git-tree-status"
              className={cn("font-mono text-caption font-medium", markClassNames[gitStatusTones[file.status]])}
            >
              {labels.mark[file.status]}
            </span>
          ) : changedFolder ? (
            <span data-slot="git-tree-changed" className="size-1.5 rounded-full bg-warning" />
          ) : null}
        </span>
      </TreeItemLabel>
    </TreeItem>
  )
})

function nameOf(path: string, file: GitTreeFile | undefined, labels: GitTreeLabels) {
  return file?.status ? `${path}, ${labels.status[file.status]}` : path
}

/**
 * A repository's files at a commit, folders first, with changed files marked by status (added, modified, deleted,
 * renamed) and folders that hold a change marked too. UI SDK's Tree underneath: arrows, typeahead, Left/Right to
 * close and open folders. Rows virtualize, so 100,000 files render only what's in view.
 */
function GitTree({
  "aria-label": label,
  files,
  expanded,
  defaultExpanded,
  onExpandedChange,
  current,
  onOpenFile,
  labels: labelOverrides,
  estimateSize = 32,
  findable = false,
  className,
  onFocus,
  ...props
}: GitTreeProps) {
  const labels = useMemo(() => ({ ...gitTreeLabels, ...labelOverrides }), [labelOverrides])
  const index = useMemo(() => indexGitFiles(files), [files])
  const items = useMemo(() => treeFromPaths(index.paths), [index])
  const folders = useMemo(() => {
    const set = new Set<string>()
    const walk = (list: readonly TreeItemData[]) => {
      for (const item of list) {
        if (!item.children) continue
        set.add(item.value)
        walk(item.children)
      }
    }
    walk(items)
    return set
  }, [items])

  const fileSet = useMemo(() => new Set(index.paths), [index])
  const lookup = useMemo(
    () => ({
      kind: (path: string) =>
        folders.has(path) ? ("folder" as const) : fileSet.has(path) ? ("file" as const) : undefined,
      entries: () => index.paths.map((path) => ({ value: path, label: nameOf(path, index.status.get(path), labels) })),
    }),
    [folders, fileSet, index, labels],
  )
  const handle = usePrimitive(gitTree, {
    lookup,
    expanded,
    defaultExpanded: defaultExpanded ?? [...index.changedFolders],
    onExpandedChange,
    onOpenFile,
  })
  const state = useInstanceState<typeof handle.state>(handle.instance)
  const rows = useMemo(() => visibleTreeRows(items, state.expanded), [items, state.expanded])
  const open = useMemo(() => new Set(state.expanded), [state.expanded])

  const keyAt = useCallback((at: number) => rows[at]?.item.value ?? String(at), [rows])
  const nameAt = useCallback((at: number) => rows[at]?.item.label ?? "", [rows])
  const { setScroller, anchor, ...virtual } = useTrailRows({
    count: rows.length,
    estimate: estimateSize,
    getKey: keyAt,
    text: nameAt,
    findable,
  })
  const context = useMemo<RowContext>(
    () => ({ status: index.status, changedFolders: index.changedFolders, labels }),
    [index, labels],
  )
  return usePart(
    handle,
    "root",
    {},
    {
      ...props,
      "aria-label": label,
      className: cn("flex min-h-0 min-w-0 flex-col", indentSize, className),
      onFocus: (event: FocusEvent<HTMLDivElement>) => {
        onFocus?.(event)
        if (!virtual.virtual || !(event.target instanceof Element)) return
        const at = Number(event.target.closest<HTMLElement>("[data-index]")?.dataset.index ?? Number.NaN)
        if (!Number.isNaN(at)) virtual.pin(at)
      },
      children: (
        <div
          ref={setScroller}
          className={cn("min-h-0 flex-1 overflow-y-auto", findable && "max-h-(--git-tree-height)")}
        >
          <div ref={anchor} className="min-w-0">
            <Tree
              aria-label={label}
              // The tree's own expand and collapse would list every path a second time beside open, expand and collapse.
              data-agent-hidden=""
              items={items}
              mode="none"
              current={current ?? null}
              expanded={state.expanded as string[]}
              onExpandedChange={(next, change) =>
                handle.api.setExpanded(next, { reason: change.reason, event: change.event })
              }
              onAction={(path, { event }) => {
                if (!folders.has(path) && onOpenFile) handle.api.open(path, { reason: "item-press", event })
              }}
              onHighlight={(_path, { index: at }) => {
                if (virtual.virtual && at >= 0) virtual.scrollToIndex(at)
              }}
              style={virtual.absolute ? { height: virtual.height } : undefined}
              className={cn("flex min-w-0 flex-col outline-none", virtual.virtual && "relative")}
            >
              {virtual.segments.map((segment) => {
                if (segment.type === "gap") {
                  return (
                    <div
                      key={segment.key}
                      aria-hidden="true"
                      data-slot="git-tree-gap"
                      style={{ height: segment.size }}
                    />
                  )
                }
                const { index: at, top } = segment
                const row = rows[at]
                if (!row) return null
                return (
                  <GitTreeRow
                    key={row.item.value}
                    item={row.item}
                    level={row.level}
                    index={at}
                    top={top}
                    expanded={open.has(row.item.value)}
                    context={context}
                    measure={virtual.measure}
                    textSlot={virtual.textSlot}
                  />
                )
              })}
            </Tree>
          </div>
        </div>
      ),
    },
  )
}

export { GitTree, gitTreeLabels }
export type { GitTreeLabels, GitTreeProps }

import { createChange, definePrimitive, dispatch, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

import { parentsOf } from "@/lib/git-status"

type GitTreeChangeReason = "item-press" | "trigger-press" | "list-navigation" | "find-in-page" | "imperative"

/** How the primitive reads the tree without a copy of every path. */
type GitTreeLookup = {
  kind: (path: string) => "file" | "folder" | undefined
  /** Every path as agents list them: the path, and the row's name with its status. */
  entries: () => readonly { value: string; label: string }[]
}

type GitTreeOptions = {
  lookup?: GitTreeLookup
  expanded?: readonly string[]
  defaultExpanded?: readonly string[]
  onExpandedChange?: (expanded: string[], details: ChangeDetails<GitTreeChangeReason>) => void
  onOpenFile?: (path: string, details: ChangeDetails<GitTreeChangeReason>) => void
}

function reasonOf(options: unknown): { reason: GitTreeChangeReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<GitTreeChangeReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

const gitTree = definePrimitive({
  name: "git-tree",
  options: {
    lookup: "value",
    expanded: "list",
    defaultExpanded: "list",
    onExpandedChange: "callback",
    onOpenFile: "callback",
  },
  state: (options: GitTreeOptions) => ({ expanded: [...(options.expanded ?? options.defaultExpanded ?? [])] }),
  sync: (options) => (options.expanded === undefined ? {} : { expanded: [...options.expanded] }),
  controlled: ["expanded"],
  api: (context) => {
    const change = createChange(context)
    // The agent bridge passes arguments unchecked.
    const check = (path: unknown, kind?: "file" | "folder") => {
      const found = typeof path === "string" ? context.options().lookup?.kind(path) : undefined
      if (!found) throw new RangeError(`No path "${String(path)}" in the tree.`)
      if (kind && found !== kind) throw new RangeError(`"${String(path)}" is a ${found}, not a ${kind}.`)
      return path as string
    }
    const setExpanded = (next: string[], options?: unknown) => change("expanded", next, reasonOf(options))
    const api = {
      setExpanded(expanded: readonly string[], options?: ChangeOptions<GitTreeChangeReason>) {
        return setExpanded([...expanded], options)
      },
      /** Opens a folder with its parents, or a file through `onOpenFile`, opening the folders it is in first. */
      open(path: string, options?: ChangeOptions<GitTreeChangeReason>) {
        const target = check(path)
        const kind = context.options().lookup?.kind(target)
        if (kind === "folder") return api.expand(target, options)
        const { expanded } = context.store.get()
        const missing = parentsOf(target).filter((folder) => !expanded.includes(folder))
        if (missing.length > 0 && !setExpanded([...expanded, ...missing], options)) return false
        if (!context.options().onOpenFile) throw new Error("This tree doesn't open files.")
        return !dispatch(context, "onOpenFile", target, reasonOf(options))
      },
      expand(path: string, options?: ChangeOptions<GitTreeChangeReason>) {
        const folder = check(path, "folder")
        const { expanded } = context.store.get()
        const missing = [...parentsOf(folder), folder].filter((open) => !expanded.includes(open))
        return missing.length === 0 ? true : setExpanded([...expanded, ...missing], options)
      },
      collapse(path: string, options?: ChangeOptions<GitTreeChangeReason>) {
        const folder = check(path, "folder")
        const { expanded } = context.store.get()
        return expanded.includes(folder)
          ? setExpanded(
              expanded.filter((open) => open !== folder),
              options,
            )
          : true
      },
      paths: () => context.options().lookup?.entries() ?? [],
    }
    return api
  },
  slots: (slot) => ({ root: slot({ role: "region" }) }),
  agent: { actions: ["open", "expand", "collapse"], items: (api) => api.paths() },
})

export { gitTree }
export type { GitTreeChangeReason, GitTreeLookup, GitTreeOptions }

import type { Tone } from "@/lib/tone"

type GitFileStatus = "added" | "modified" | "deleted" | "renamed"

/** A file in the tree; `status` marks it changed, and a rename says where it came `from`. */
type GitTreeFile = { path: string; status?: GitFileStatus; from?: string }

const gitStatusTones: Record<GitFileStatus, Tone> = {
  added: "success",
  modified: "warning",
  deleted: "destructive",
  renamed: "info",
}

function parentsOf(path: string) {
  const parents: string[] = []
  for (let at = path.indexOf("/"); at > 0; at = path.indexOf("/", at + 1)) parents.push(path.slice(0, at))
  return parents
}

type GitTreeIndex = {
  paths: string[]
  status: ReadonlyMap<string, GitTreeFile>
  /** Folders with a changed file anywhere inside them. */
  changedFolders: ReadonlySet<string>
}

/** The tree's paths, each changed file by path, and every folder that holds a change: O(files + changes × depth). */
function indexGitFiles(files: readonly (string | GitTreeFile)[]): GitTreeIndex {
  const paths: string[] = []
  const status = new Map<string, GitTreeFile>()
  const changedFolders = new Set<string>()
  for (const file of files) {
    if (typeof file === "string") {
      paths.push(file)
      continue
    }
    paths.push(file.path)
    if (!file.status) continue
    status.set(file.path, file)
    for (const folder of parentsOf(file.path)) changedFolders.add(folder)
  }
  return { paths, status, changedFolders }
}

export { gitStatusTones, indexGitFiles, parentsOf }
export type { GitFileStatus, GitTreeFile, GitTreeIndex }

import type { PrimitiveInstance } from "@ui-sdk/core"
import { useSyncExternalStore } from "react"

/** A primitive instance's state, re-rendering the component that reads it on every change. */
function useInstanceState<State>(instance: PrimitiveInstance): State {
  return useSyncExternalStore(instance.subscribe, instance.get, instance.get) as State
}

export { useInstanceState }

import { useCallback } from "react"

import { useFindableRows } from "@/components/ui/use-findable-rows"
import { useFlowRows } from "@/components/ui/use-flow-rows"

type TrailRowsOptions = {
  count: number
  /** A row's estimated height in px before it is measured. */
  estimate: number
  getKey: (index: number) => string
  /** A row's text for find in page, in the pieces its `textSlot` elements hold. */
  text: (index: number) => string | readonly string[]
  /** Find in page reaches rows that aren't rendered, through UI SDK's virtualizer and findable layers. */
  findable: boolean
}

/** A rendered row, at `top` px in an absolutely positioned box, or in flow; or the space of rows not rendered. */
type TrailSegment = { type: "row"; index: number; top?: number } | { type: "gap"; size: number; key: string }

const noop = () => {}

/**
 * The rows of a long trail or tree. By default TanStack Virtual's rows in document flow (`use-flow-rows`), the
 * fastest to move through; with `findable`, UI SDK's virtualizer, whose findable layers let find in page reach the
 * rows that aren't rendered, at a cost `tooling/git-bench.mjs` measures. Only one of them ever holds rows.
 */
function useTrailRows({ count, estimate, getKey, text, findable }: TrailRowsOptions) {
  const flow = useFlowRows({ count: findable ? 0 : count, estimateSize: estimate, getKey })
  const { setScroller, ...layered } = useFindableRows({
    count: findable ? count : 0,
    estimate,
    getKey,
    text,
    findable,
  })
  const absolute = findable && layered.enabled

  let segments: TrailSegment[]
  if (absolute) segments = layered.items.map((item) => ({ type: "row", index: item.index, top: item.start }))
  else if (findable) segments = Array.from({ length: count }, (_, index) => ({ type: "row", index }))
  else
    segments = flow.segments.map((segment) =>
      segment.type === "row" ? { type: "row", index: segment.index } : segment,
    )

  // Rows are memoized: everything they get keeps its identity across scrolls.
  const { measureElement } = flow
  const { measure: measureLayered } = layered
  const measure = useCallback(
    (index: number, el: HTMLElement | null) => {
      if (absolute) return measureLayered(index, el)
      measureElement?.(el)
      return noop
    },
    [absolute, measureLayered, measureElement],
  )
  const { pin: pinFlow, scrollToIndex: scrollFlow } = flow
  const { pin: pinLayered, scrollToIndex: scrollLayered } = layered
  const pin = useCallback(
    (index: number | undefined) => (absolute ? pinLayered(index) : pinFlow(index)),
    [absolute, pinFlow, pinLayered],
  )
  const { renderNow } = flow
  /** Renders a row wherever the list is scrolled and scrolls to it, like a branch's head about to take focus. */
  const reveal = useCallback(
    (index: number) => {
      if (absolute) {
        scrollLayered(index)
        return
      }
      renderNow(index)
      scrollFlow(index)
    },
    [absolute, renderNow, scrollFlow, scrollLayered],
  )
  const scrollToIndex = useCallback(
    (index: number) => (absolute ? scrollLayered(index) : scrollFlow(index)),
    [absolute, scrollFlow, scrollLayered],
  )

  return {
    /** Rows render only in view, by either engine. */
    virtual: absolute || flow.enabled,
    /** The rows' box is `height` px tall and rows sit at their `top`. */
    absolute,
    height: absolute ? layered.size : undefined,
    segments,
    /** Pass as the `ref` of the element the rows are in, in flow. */
    anchor: flow.anchor,
    /** Pass as the `ref` of the scroller, for UI SDK's virtualizer. */
    setScroller,
    measure: absolute || flow.enabled ? measure : undefined,
    textSlot: absolute ? layered.findableText : undefined,
    pin,
    scrollToIndex,
    reveal,
  }
}

export { useTrailRows }
export type { TrailRowsOptions, TrailSegment }

"use client"

// TanStack Virtual's rows in document flow, as virtual-rows had them before it moved to UI SDK's virtualizer: kept for
// CommitHistory and GitTree, whose held arrow keys reached the next paint in 12 ms at the 95th percentile on it and
// 20-26 ms on UI SDK's (tooling/git-bench.mjs, 50,000 commits, 1x CPU). Everything else uses virtual-rows.

import {
  defaultRangeExtractor,
  useVirtualizer,
  useWindowVirtualizer,
  type Range,
  type VirtualItem,
} from "@tanstack/react-virtual"
import { useCallback, useMemo, useRef, useState } from "react"
import { flushSync } from "react-dom"

/** `"auto"` virtualizes past `VIRTUALIZE_THRESHOLD` rows. */
type Virtualize = boolean | "auto"

const VIRTUALIZE_THRESHOLD = 200

type VirtualRowsOptions = {
  count: number
  virtualize?: Virtualize
  /** A row's estimated height in px before it is measured. */
  estimateSize?: number | ((index: number) => number)
  getKey: (index: number) => string
  overscan?: number
}

/** A rendered row, or a gap holding the space of the rows from `from` up to `to` that aren't rendered. */
type Segment =
  | { type: "row"; index: number; key: string }
  | { type: "gap"; size: number; from: number; to: number; key: string }

type Scroller = { element: HTMLElement | null; margin: number }

function scrollParentOf(el: HTMLElement) {
  for (let node = el.parentElement; node; node = node.parentElement) {
    const { overflowY } = getComputedStyle(node)
    if ((overflowY === "auto" || overflowY === "scroll") && node.scrollHeight > node.clientHeight + 1) return node
  }
  return null
}

function marginIn(el: HTMLElement, scroller: HTMLElement | null) {
  const top = el.getBoundingClientRect().top
  if (!scroller) return top + globalThis.scrollY
  return top - scroller.getBoundingClientRect().top + scroller.scrollTop
}

function isVirtual(virtualize: Virtualize, count: number) {
  return virtualize === "auto" ? count > VIRTUALIZE_THRESHOLD : virtualize
}

function sizeOf(estimateSize: VirtualRowsOptions["estimateSize"]) {
  if (typeof estimateSize === "function") return estimateSize
  const size = estimateSize ?? 52
  return () => size
}

/**
 * Renders only the rows in view (and `keep`), in document flow: gaps take the place of the rows in between, so a
 * table keeps its rows in `tbody` and a list its items in `ul`. It scrolls with the nearest scrolling ancestor of
 * the element given to `anchor`, or the window when there is none.
 */
function useFlowRows({ count, virtualize = "auto", estimateSize, getKey, overscan = 8 }: VirtualRowsOptions) {
  const enabled = isVirtual(virtualize, count)
  const [scroller, setScroller] = useState<Scroller | null>(null)
  const estimate = useMemo(() => sizeOf(estimateSize), [estimateSize])
  // The focused row stays rendered while scrolled away, so focus isn't lost. Pinning it on every focus move
  // re-renders nothing; the range picks it up on the next scroll, or at once when `version` changes.
  const pinned = useRef<number | undefined>(undefined)
  const [version, setVersion] = useState(0)

  const rangeExtractor = useCallback(
    (range: Range) => {
      const indexes = defaultRangeExtractor(range)
      const keep = pinned.current
      if (version < 0 || keep === undefined || keep >= range.count || indexes.includes(keep)) return indexes
      return [...indexes, keep].toSorted((a, b) => a - b)
    },
    [version],
  )

  const shared = {
    count,
    estimateSize: estimate,
    getItemKey: getKey,
    overscan,
    rangeExtractor,
    scrollMargin: scroller?.margin ?? 0,
  }
  // oxlint-disable-next-line react/incompatible-library -- TanStack Virtual's instance is read during render by design, so the compiler leaves this hook unmemoized
  const element = useVirtualizer<HTMLElement, HTMLElement>({
    ...shared,
    enabled: enabled && scroller !== null && scroller.element !== null,
    getScrollElement: () => scroller?.element ?? null,
  })
  const windowed = useWindowVirtualizer<HTMLElement>({
    ...shared,
    enabled: enabled && scroller !== null && scroller.element === null,
  })
  const virtualizer = scroller?.element ? element : windowed

  const anchor = useCallback(
    (node: HTMLElement | null) => {
      if (!node || !enabled) return
      const scrollElement = scrollParentOf(node)
      setScroller({ element: scrollElement, margin: marginIn(node, scrollElement) })
    },
    [enabled],
  )

  let segments: Segment[]
  if (!enabled) {
    segments = Array.from({ length: count }, (_, index) => ({ type: "row", index, key: getKey(index) }))
  } else if (scroller === null) {
    segments = count > 0 ? [{ type: "gap", size: count * estimate(0), from: 0, to: count, key: "gap-start" }] : []
  } else {
    segments = segmentsOf(virtualizer.getVirtualItems(), virtualizer.getTotalSize(), scroller.margin, count)
  }
  const margin = scroller?.margin ?? 0
  const offsetOf = useCallback(
    (index: number) => {
      const item = virtualizer.measurementsCache[index]
      if (!item) return { start: index * estimate(index), size: estimate(index) }
      return { start: item.start - margin, size: item.size }
    },
    [virtualizer, margin, estimate],
  )

  const scrollToIndex = useCallback(
    (index: number) => {
      if (enabled) virtualizer.scrollToIndex(index, { align: "auto" })
    },
    [enabled, virtualizer],
  )
  const pin = useCallback((index: number | undefined) => {
    pinned.current = index
  }, [])
  /** Renders a row now, wherever the list is scrolled, like one an agent is about to activate. */
  const renderNow = useCallback(
    (index: number) => {
      if (!enabled) return
      pinned.current = index
      flushSync(() => setVersion((current) => current + 1))
    },
    [enabled],
  )

  return {
    enabled,
    anchor,
    segments,
    pin,
    renderNow,
    rendered: (index: number) => !enabled || segments.some((s) => s.type === "row" && s.index === index),
    measureElement: enabled ? virtualizer.measureElement : undefined,
    scrollToIndex,
    /** Where each row starts in the anchor and how tall it is, measured or estimated. */
    offsetOf,
  }
}

function segmentsOf(items: VirtualItem[], total: number, margin: number, count: number) {
  const segments: Segment[] = []
  let position = 0
  let next = 0
  for (const item of items) {
    const start = item.start - margin
    if (item.index > next) {
      const key = next === 0 ? "gap-start" : `gap-${String(next)}`
      segments.push({ type: "gap", size: Math.max(0, start - position), from: next, to: item.index, key })
    }
    segments.push({ type: "row", index: item.index, key: String(item.key) })
    position = start + item.size
    next = item.index + 1
  }
  if (next < count)
    segments.push({ type: "gap", size: Math.max(0, total - position), from: next, to: count, key: "gap-end" })
  return segments
}

export { useFlowRows }

import { createVirtualizer } from "@ui-sdk/core"
import { useCallback, useEffect, useLayoutEffect, useState, useSyncExternalStore } from "react"

/** Past this many rows only the rows in view render. */
const FINDABLE_ROWS_THRESHOLD = 200

type FindableRowsOptions = {
  count: number
  /** A row's estimated height in px before it is measured. */
  estimate: number
  getKey: (index: number) => string
  /** The text find in page should find in a row: what it shows, in the pieces its `findableText` elements hold. */
  text: (index: number) => string | readonly string[]
  /** Keeps rows that aren't rendered findable, through UI SDK's findable layers, built once the page is idle. */
  findable: boolean
}

type Latest = Omit<FindableRowsOptions, "findable">

const noKeep: readonly number[] = []

// The layers hold a stand-in for every row, so they wait until the first paint is done and the page is idle.
function whenIdle(run: () => void) {
  const idle = globalThis.requestIdleCallback as typeof requestIdleCallback | undefined
  const cancelIdle = globalThis.cancelIdleCallback as typeof cancelIdleCallback | undefined
  if (idle && cancelIdle) {
    const handle = idle(run, { timeout: 2000 })
    return () => cancelIdle(handle)
  }
  const timer = setTimeout(run, 200)
  return () => clearTimeout(timer)
}

/** A virtualizer that reads the newest options, which `update` swaps in; outside React, so it can hold them. */
function createRows(initial: Latest) {
  let latest = initial
  let keep = noKeep
  const virtual = createVirtualizer({
    count: () => latest.count,
    estimate: () => latest.estimate,
    key: (index) => latest.getKey(index),
    overscan: 8,
    keep: () => keep,
    findable: (index) => latest.text(index),
  })
  return {
    virtual,
    update(next: Latest) {
      const same =
        latest.count === next.count &&
        latest.getKey === next.getKey &&
        latest.text === next.text &&
        latest.estimate === next.estimate
      if (same) return
      latest = next
      virtual.refresh()
    },
    // Read on the virtualizer's next update, like the scroll a key press makes: refreshing here would render the
    // list on every focus move.
    pin(index: number | undefined) {
      if (keep[0] !== index) keep = index === undefined ? noKeep : [index]
    },
  }
}

/**
 * Rows on UI SDK's virtualizer: past 200 rows, only those in view render, absolutely positioned in a box as tall as
 * every row and measured as they render, so their heights can change. With `findable`, find in page reaches the
 * rows that aren't rendered and scrolls to the one it matched. Give the scroller a bounded height.
 */
function useFindableRows({ count, estimate, getKey, text, findable }: FindableRowsOptions) {
  const enabled = count > FINDABLE_ROWS_THRESHOLD
  const [rows] = useState(() => createRows({ count, estimate, getKey, text }))
  const { virtual } = rows
  const [scroller, setScroller] = useState<HTMLElement | null>(null)

  // The virtualizer reads the newest options when it computes; `update` tells it only when they changed.
  useLayoutEffect(() => {
    rows.update({ count, estimate, getKey, text })
  })

  useEffect(() => {
    if (!scroller || !enabled) return undefined
    let disconnect = virtual.connect(scroller)
    if (!findable) return () => disconnect()
    const cancel = whenIdle(() => {
      disconnect()
      disconnect = virtual.connect(scroller, { findable: true })
    })
    return () => {
      cancel()
      disconnect()
    }
  }, [virtual, scroller, enabled, findable])

  const items = useSyncExternalStore(virtual.subscribe, virtual.items, virtual.items)
  const size = useSyncExternalStore(virtual.subscribe, virtual.size, virtual.size)

  /** Keeps a row rendered wherever the list scrolls, like the one with focus. */
  const pin = useCallback((index: number | undefined) => rows.pin(index), [rows])
  const scrollToIndex = useCallback(
    (index: number) => {
      if (enabled) virtual.scrollToIndex(index)
    },
    [virtual, enabled],
  )

  return {
    enabled,
    items,
    size,
    /** The scroller, the nearest element that scrolls the rows: pass it as its `ref`. */
    setScroller,
    measure: virtual.measure,
    findableText: virtual.findableText,
    pin,
    scrollToIndex,
  }
}

export { FINDABLE_ROWS_THRESHOLD, useFindableRows }
export type { FindableRowsOptions }
